from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.core.extern import Extern, _EErr
from exo.API_scheduling import *


class _Sqrt(Extern):
    def __init__(self):
        # Name is only for pretty-printing; C code comes from compile()
        super().__init__("sqrt_exo")

    def typecheck(self, args):
        if len(args) != 1:
            raise _EErr(f"expected 1 argument, got {len(args)}")
        arg_type = args[0].type
        if not arg_type.is_real_scalar():
            raise _EErr(
                f"expected argument to be a real scalar value, but got type {arg_type}"
            )
        return arg_type

    def compile(self, args, prim_type):
        # Use PolyBench's SQRT_FUN macro for correct precision
        return f"SQRT_FUN(({prim_type}){args[0]})"

    def globl(self, prim_type):
        # SQRT_FUN is provided by the PolyBench headers, but we may still need math.h
        return "#include <math.h>"

    def interpret(self, args):
        import math
        return math.sqrt(args[0])


sqrt_exo = _Sqrt()


class _ClampStddev(Extern):
    # Implements: x <= eps ? 1.0 : x
    # Used to avoid value-dependent conditionals in Exo object code.
    def __init__(self):
        super().__init__("clamp_stddev")

    def typecheck(self, args):
        if len(args) != 2:
            raise _EErr(f"expected 2 arguments, got {len(args)}")
        x_t = args[0].type
        eps_t = args[1].type
        if not (x_t.is_real_scalar() and eps_t.is_real_scalar()):
            raise _EErr(
                f"expected real scalar arguments, but got types {x_t} and {eps_t}"
            )
        # Result has the same type as x
        return x_t

    def compile(self, args, prim_type):
        # Use SCALAR_VAL(1.0) to match PolyBench's DATA_TYPE precisely
        return f"(({args[0]} <= {args[1]}) ? SCALAR_VAL(1.0) : {args[0]})"

    def globl(self, prim_type):
        # SCALAR_VAL is defined in the PolyBench headers
        return ""

    def interpret(self, args):
        x, eps = args
        return 1.0 if x <= eps else x


clamp_stddev = _ClampStddev()


@proc
def kernel_correlation(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    corr: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
    stddev: DATA_TYPE[m] @ DRAM,
):
    eps: DATA_TYPE
    sqrt_float_n: DATA_TYPE
    diff: DATA_TYPE
    centered: DATA_TYPE

    # eps = 0.1 (same as SCALAR_VAL(0.1) in the original C code)
    eps = 0.1

    # Precompute sqrt(float_n) once; used in normalization.
    sqrt_float_n = sqrt_exo(float_n)

    # --------------------------------------------------------------------
    # Compute mean of each column using row-major traversal for better
    # spatial locality on data[i, j].
    # mean[j] = (1 / n) * sum_i data[i, j]
    # --------------------------------------------------------------------
    for j in seq(0, m):
        mean[j] = 0.0

    for i in seq(0, n):
        for j in seq(0, m):
            mean[j] += data[i, j]

    for j in seq(0, m):
        mean[j] = mean[j] / float_n

    # --------------------------------------------------------------------
    # Compute standard deviation of each column, again in row-major order:
    # stddev[j] = sqrt( (1 / n) * sum_i (data[i, j] - mean[j])^2 )
    # Then clamp very small stddev to 1.0 to avoid division by ~0.
    # --------------------------------------------------------------------
    for j in seq(0, m):
        stddev[j] = 0.0

    for i in seq(0, n):
        for j in seq(0, m):
            diff = data[i, j] - mean[j]
            stddev[j] += diff * diff

    for j in seq(0, m):
        stddev[j] = stddev[j] / float_n
        stddev[j] = sqrt_exo(stddev[j])
        stddev[j] = clamp_stddev(stddev[j], eps)

    # --------------------------------------------------------------------
    # Precompute the inverse scaling factor 1 / (sqrt(float_n) * stddev[j])
    # so that the normalization loop only performs a multiply.
    # We overwrite stddev[j] with its inverse scale factor.
    # --------------------------------------------------------------------
    for j in seq(0, m):
        stddev[j] = 1.0 / (sqrt_float_n * stddev[j])

    # --------------------------------------------------------------------
    # Center and scale the columns:
    # data[i, j] = (data[i, j] - mean[j]) / (sqrt(float_n) * orig_stddev[j])
    #            = (data[i, j] - mean[j]) * stddev[j]   (after overwrite)
    # Traversal is row-major (i outer, j inner).
    # --------------------------------------------------------------------
    for i in seq(0, n):
        for j in seq(0, m):
            centered = data[i, j] - mean[j]
            data[i, j] = centered * stddev[j]

    # --------------------------------------------------------------------
    # Compute the m x m correlation matrix as corr = data^T * data.
    # We accumulate only the strict upper triangle (i < j) and later
    # symmetrize and fill the diagonal with 1.0, matching the original
    # PolyBench correlation semantics.
    # --------------------------------------------------------------------
    # Initialize upper triangle (excluding the diagonal).
    for i in seq(0, m):
        for j in seq(i + 1, m):
            corr[i, j] = 0.0

    # Accumulate outer products row by row:
    # for each sample k, use row data[k, :] to update all (i, j) pairs.
    for k in seq(0, n):
        for i in seq(0, m):
            for j in seq(i + 1, m):
                corr[i, j] += data[k, i] * data[k, j]

    # Symmetrize and set the diagonal to 1.0.
    for i in seq(0, m):
        corr[i, i] = 1.0
        for j in seq(i + 1, m):
            corr[j, i] = corr[i, j]


# ----------------------------------------------------------------------
# Scheduling: keep the algorithmic structure but tile the correlation
# accumulation loop along the samples dimension (k) to improve cache
# behavior on very large n. TILE_N can be tuned per target machine.
# ----------------------------------------------------------------------
kernel_correlation_base = kernel_correlation

TILE_N = 32  # tile size along the samples (n) dimension

p = kernel_correlation_base
p = simplify(p)
p = divide_loop(p, "k", TILE_N, ("ko", "ki"), tail="guard")

kernel_correlation = p
EXO END
